#[test]
fn error_gate_6_worked_examples_are_lossless_and_ast_direct_parity() {
    fn outline(node: &SyntaxNode, entries: &mut Vec<(SyntaxKind, Range<usize>)>) {
        for element in node.children_with_tokens() {
            entries.push((element.kind(), syntax_range(element.text_range())));
            if let Some(child) = element.into_node() {
                outline(&child, entries);
            }
        }
    }

    fn parse_ast<'source>(source: &'source str) -> ErrorDeclaration<'source> {
        let mut input = SourceInput::new(source);
        let mut local = ParseLocal::new();
        let mut sink = chasa::LatestSink::new();
        let mut cut = false;
        let declaration = parse_error_declaration_isolated(
            In::new(&mut input, &mut sink, IsCut::new(&mut cut)).set_local(&mut local),
        )
        .expect("accepted isolated Error intro");
        assert_eq!(input.remainder(), "", "AST remainder: {source:?}");
        assert!(sink.take_merged().is_none(), "AST sink: {source:?}");
        assert!(!cut, "AST cut: {source:?}");
        declaration
    }

    fn commit_direct(
        source: &str,
    ) -> (
        Recovered<Range<usize>>,
        SyntaxNode,
        Vec<CommittedRecoveryRecord>,
    ) {
        let mut input = SourceInput::new(source);
        let mut local = ParseLocal::new();
        let mut sink = chasa::LatestSink::new();
        let mut cut = false;
        let i = In::new(&mut input, &mut sink, IsCut::new(&mut cut)).set_local(&mut local);
        let mut probe = Probe::new(i);
        let intro = probe
            .input()
            .run(recognize_error_statement_intro)
            .expect("accepted Error intro");
        let mut committed = probe.commit(FullCstOutput::new(source));
        committed.start_node(SyntaxKind::Root);
        let range = commit_error_declaration_isolated(&mut committed, intro);
        committed.finish_node();
        let output = committed.into_output();
        assert_eq!(input.remainder(), "", "direct remainder: {source:?}");
        assert!(sink.take_merged().is_none(), "direct sink: {source:?}");
        assert!(!cut, "direct cut: {source:?}");
        let recoveries = output.committed_recoveries().to_vec();
        (
            range,
            SyntaxNode::new_root(output.finish_complete()),
            recoveries,
        )
    }

    for (source, expected) in [
        (
            "error fs_err:\n  not_found str\n  denied str",
            vec![
                (SyntaxKind::ErrorKw, 0..5),
                (SyntaxKind::Whitespace, 5..6),
                (SyntaxKind::Identifier, 6..12),
                (SyntaxKind::Colon, 12..13),
                (SyntaxKind::Newline, 13..14),
                (SyntaxKind::Whitespace, 14..16),
                (SyntaxKind::EnumVariant, 16..29),
                (SyntaxKind::Identifier, 16..25),
                (SyntaxKind::Whitespace, 25..26),
                (SyntaxKind::TypeExpression, 26..29),
                (SyntaxKind::Identifier, 26..29),
                (SyntaxKind::Newline, 29..30),
                (SyntaxKind::Whitespace, 30..32),
                (SyntaxKind::EnumVariant, 32..42),
                (SyntaxKind::Identifier, 32..38),
                (SyntaxKind::Whitespace, 38..39),
                (SyntaxKind::TypeExpression, 39..42),
                (SyntaxKind::Identifier, 39..42),
            ],
        ),
        (
            "error io_err:\n  fs from fs_err",
            vec![
                (SyntaxKind::ErrorKw, 0..5),
                (SyntaxKind::Whitespace, 5..6),
                (SyntaxKind::Identifier, 6..12),
                (SyntaxKind::Colon, 12..13),
                (SyntaxKind::Newline, 13..14),
                (SyntaxKind::Whitespace, 14..16),
                (SyntaxKind::EnumVariant, 16..30),
                (SyntaxKind::Identifier, 16..18),
                (SyntaxKind::Whitespace, 18..19),
                (SyntaxKind::FromKw, 19..23),
                (SyntaxKind::Whitespace, 23..24),
                (SyntaxKind::TypeExpression, 24..30),
                (SyntaxKind::Identifier, 24..30),
            ],
        ),
        (
            "my error E:\n  failed",
            vec![
                (SyntaxKind::MyKw, 0..2),
                (SyntaxKind::Whitespace, 2..3),
                (SyntaxKind::ErrorKw, 3..8),
                (SyntaxKind::Whitespace, 8..9),
                (SyntaxKind::Identifier, 9..10),
                (SyntaxKind::Colon, 10..11),
                (SyntaxKind::Newline, 11..12),
                (SyntaxKind::Whitespace, 12..14),
                (SyntaxKind::EnumVariant, 14..20),
                (SyntaxKind::Identifier, 14..20),
            ],
        ),
    ] {
        let ast = parse_ast(source);
        let (range, root, recoveries) = commit_direct(source);
        assert_eq!(
            range,
            Recovered::Complete(ast.range()),
            "range parity: {source:?}"
        );
        assert_eq!(ast.range(), 0..source.len(), "AST range: {source:?}");
        assert!(matches!(
            ast.body,
            Recovered::Complete(EnumBody::Colon { .. })
        ));
        assert!(recoveries.is_empty(), "zero recovery: {source:?}");
        assert_eq!(root.to_string(), source, "lossless: {source:?}");
        let declaration = root
            .children()
            .find(|node| node.kind() == SyntaxKind::ErrorDeclaration)
            .expect("one ErrorDeclaration");
        let mut actual = Vec::new();
        outline(&declaration, &mut actual);
        assert_eq!(actual, expected, "byte-exact CST: {source:?}");
    }
}

#[test]
fn gate3b_derives_via_target_episode_companion_handoff_and_rollback() {
    let source = "derives Eq via @ with:";
    let mut ast_input = SourceInput::new(source);
    let mut ast_local = ParseLocal::new();
    let mut ast_sink = chasa::LatestSink::new();
    let mut ast_cut = false;
    let (ast, ast_remainder) = {
        let mut i = In::new(&mut ast_input, &mut ast_sink, IsCut::new(&mut ast_cut))
            .set_local(&mut ast_local);
        let start = recognize_derives_attachment_start(
            DerivesAttachmentOwner::Type,
            DerivesAttachmentPosition::Header,
            0,
            &mut i,
        )
        .expect("companion-aware derives start");
        let parsed = parse_derives_attachments_with_companion_handoff_isolated(start, &mut i);
        (parsed, i.input.remainder().to_owned())
    };
    assert_eq!(ast_remainder, " with:");
    assert!(ast.tail.is_some());
    assert!(matches!(
        ast.attachments[0]
            .clause
            .via
            .as_ref()
            .map(|via| &via.target),
        Some(Recovered::Incomplete)
    ));
    let ast_snapshot = ast_local.value_snapshot();
    assert!(ast_sink.take_merged().is_none());
    assert!(!ast_cut);

    let mut direct_input = SourceInput::new(source);
    let mut direct_local = ParseLocal::new();
    let mut direct_sink = chasa::LatestSink::new();
    let mut direct_cut = false;
    let i = In::new(
        &mut direct_input,
        &mut direct_sink,
        IsCut::new(&mut direct_cut),
    )
    .set_local(&mut direct_local);
    let mut committed = Probe::new(i).commit(FullCstOutput::new(source));
    committed.start_node(SyntaxKind::Root);
    let start = committed
        .probe(|probe| {
            recognize_derives_attachment_start(
                DerivesAttachmentOwner::Type,
                DerivesAttachmentPosition::Header,
                0,
                probe.input(),
            )
        })
        .expect("companion-aware direct derives start");
    let direct = commit_derives_attachments_with_companion_handoff_isolated(start, &mut committed);
    let direct_remainder = committed.probe(|probe| probe.input().input.remainder().to_owned());
    committed.finish_node();
    let output = committed.into_output();
    assert_eq!(direct_remainder, " with:");
    assert!(direct.tail.is_some());
    assert!(matches!(
        direct.attachments[0]
            .clause
            .via
            .as_ref()
            .map(|via| &via.target),
        Some(Recovered::Incomplete)
    ));
    let [record] = output.committed_recoveries() else {
        panic!("one companion ViaTarget recovery");
    };
    assert_eq!(
        (
            record.site.role,
            record.site.range.clone(),
            record.kind,
            record.expectations[record.primary_expectation].expected,
        ),
        (
            GrammarRole::Declaration(DeclarationRole::Derives(DerivesRole::ViaTarget)),
            15..16,
            RecoveryKind::Error,
            ExpectedSyntax::Identifier,
        ),
    );
    let mut expected_direct_snapshot = ast_snapshot;
    expected_direct_snapshot.next_diagnostic_id += 1;
    assert_eq!(direct_local.value_snapshot(), expected_direct_snapshot);
    assert!(direct_sink.take_merged().is_none());
    assert!(!direct_cut);
    let root = SyntaxNode::new_root(output.finish_prefix());
    assert_eq!(root.to_string(), "derives Eq via @");
    let recovery = root
        .descendants()
        .find(|node| node.kind() == SyntaxKind::Error)
        .expect("companion ViaTarget Error node");
    assert_eq!(
        recovery.parent().map(|parent| parent.kind()),
        Some(SyntaxKind::DerivesClause)
    );

    let source = "derives Eq via @ key";
    let mut input = SourceInput::new(source);
    let mut local = ParseLocal::new();
    let floor = local.push_yumark_delimiter(Delimiter::Parenthesis);
    local.push_yumark_frame(crate::session::YumarkFrame::EmbeddedYulang {
        owner: crate::session::YumarkOwner::InlineReference,
        outer_kind: crate::session::YumarkEmbeddedOuterKind::Paired(Delimiter::Parenthesis),
        delimiter_floor: floor,
    });
    let retained_fact = crate::session::YumarkEmbeddedRecoveryFact {
        spec: crate::session::RecoverySiteSpec {
            role: GrammarRole::Declaration(DeclarationRole::Derives(DerivesRole::RoleReference)),
            expected: ExpectedSyntax::TypeExpression,
        },
        range: 0..0,
        kind: RecoveryKind::Missing,
        unexpected: None,
    };
    local.record_yumark_embedded_recovery(retained_fact.clone());
    let local_before = local.value_snapshot();
    let mut sink: chasa::LatestSink<usize, chasa::error::std::StdErr<char>> =
        chasa::LatestSink::new();
    <chasa::LatestSink<usize, chasa::error::std::StdErr<char>> as ErrorSink<usize>>::push(
        &mut sink,
        4..5,
        chasa::error::std::StdErr::Expected(chasa::error::std::Expected::new(
            81,
            "preseeded-derives-via",
            (),
        )),
    );
    let sink_before = format!("{sink:?}");
    let mut cut = false;
    let i = In::new(&mut input, &mut sink, IsCut::new(&mut cut)).set_local(&mut local);
    let mut committed = Probe::new(i).commit(FullCstOutput::new(source));
    committed.start_node(SyntaxKind::Root);
    let (attachments, facts) = committed.probe(|probe| {
        let i = probe.input();
        let checkpoint = i.checkpoint();
        let errors_checkpoint = i.errors_checkpoint();
        let attachments = recognize_derives_attachment_start(
            DerivesAttachmentOwner::Type,
            DerivesAttachmentPosition::Header,
            0,
            i,
        )
        .map(|start| parse_derives_attachments_isolated(start, i));
        let facts = i.local.drain_yumark_embedded_recoveries();
        i.rollback(checkpoint);
        i.errors_rollback(errors_checkpoint);
        (attachments, facts)
    });
    let attachments = attachments.expect("accepted derives attachment candidate");
    let [attachment] = attachments.as_slice() else {
        panic!("one actual derives attachment clause");
    };
    let via = attachment
        .clause
        .via
        .as_ref()
        .expect("one actual via clause");
    assert!(
        matches!(&via.target, Recovered::Complete(target)
            if target.text() == "key" && target.range() == (17..20)),
        "ViaTarget recovery retries the real AST slot",
    );
    let [retained_before_rollback, actual] = facts.as_slice() else {
        panic!("preseeded and actual ViaTarget facts");
    };
    assert_eq!(retained_before_rollback, &retained_fact);
    assert_eq!(
        (
            actual.spec.role,
            actual.spec.expected,
            actual.range.clone(),
            actual.kind,
            actual.unexpected,
        ),
        (
            GrammarRole::Declaration(DeclarationRole::Derives(DerivesRole::ViaTarget)),
            ExpectedSyntax::Identifier,
            15..17,
            RecoveryKind::Error,
            Some(crate::session::UnexpectedCategory::OtherCharacter),
        ),
    );
    let (position, remainder, local_after, retained) = committed.probe(|probe| {
        let i = probe.input();
        (
            i.pos(),
            i.input.remainder().to_owned(),
            i.local.value_snapshot(),
            i.local.drain_yumark_embedded_recoveries(),
        )
    });
    committed.finish_node();
    let output = committed.into_output();
    assert_eq!(position, 0);
    assert_eq!(remainder, source);
    assert_eq!(local_after, local_before);
    assert_eq!(retained, vec![retained_fact]);
    assert!(output.committed_recoveries().is_empty());
    assert_eq!(SyntaxNode::new_root(output.finish_prefix()).to_string(), "");
    assert_eq!(format!("{sink:?}"), sink_before);
    assert_eq!(
        sink.take_merged(),
        Some(chasa::error::std::StdSummary {
            unexpected: None,
            expected: vec![chasa::error::std::Expected::new(
                81,
                "preseeded-derives-via",
                (),
            )],
        }),
    );
    assert!(!cut);
    assert!(matches!(
        local.pop_yumark_frame(),
        Some(crate::session::YumarkFrame::EmbeddedYulang { .. })
    ));
    local.pop_yumark_delimiter(floor, Delimiter::Parenthesis);
}

#[test]
fn error_gate_7_recovery_matrix_uses_error_outer_roles() {
    type Recovery = (RecoveryKind, GrammarRole, Range<usize>);

    fn ast<'source>(source: &'source str) -> (ErrorDeclaration<'source>, String) {
        let mut input = SourceInput::new(source);
        let mut local = ParseLocal::new();
        let mut sink = chasa::LatestSink::new();
        let mut cut = false;
        let declaration = parse_error_declaration_isolated(
            In::new(&mut input, &mut sink, IsCut::new(&mut cut)).set_local(&mut local),
        )
        .expect("accepted isolated Error intro");
        assert!(sink.take_merged().is_none(), "AST sink: {source:?}");
        assert!(!cut, "AST cut: {source:?}");
        (declaration, input.remainder().to_owned())
    }

    fn direct(source: &str) -> (Recovered<Range<usize>>, String, Vec<Recovery>) {
        let mut input = SourceInput::new(source);
        let mut local = ParseLocal::new();
        let mut sink = chasa::LatestSink::new();
        let mut cut = false;
        let i = In::new(&mut input, &mut sink, IsCut::new(&mut cut)).set_local(&mut local);
        let mut probe = Probe::new(i);
        let intro = probe
            .input()
            .run(recognize_error_statement_intro)
            .expect("accepted Error intro");
        let mut committed = probe.commit(FullCstOutput::new(source));
        committed.start_node(SyntaxKind::Root);
        let range = commit_error_declaration_isolated(&mut committed, intro);
        let remainder = committed.probe(|probe| probe.input().input.remainder().to_owned());
        committed.finish_node();
        let output = committed.into_output();
        let records = output
            .committed_recoveries()
            .iter()
            .map(|record| (record.kind, record.site.role, record.site.range.clone()))
            .collect::<Vec<_>>();
        if remainder.is_empty() {
            let root = SyntaxNode::new_root(output.finish_complete());
            assert_eq!(
                root.descendants()
                    .filter(|node| matches!(node.kind(), SyntaxKind::Missing | SyntaxKind::Error))
                    .count(),
                records.len(),
                "one direct recovery node per record: {source:?}",
            );
            assert_eq!(
                root.to_string(),
                source,
                "lossless direct recovery: {source:?}"
            );
        }
        assert!(sink.take_merged().is_none(), "direct sink: {source:?}");
        assert!(!cut, "direct cut: {source:?}");
        (range, remainder, records)
    }

    fn run<'source>(
        source: &'source str,
    ) -> (
        ErrorDeclaration<'source>,
        String,
        Recovered<Range<usize>>,
        String,
        Vec<Recovery>,
    ) {
        let (declaration, ast_remainder) = ast(source);
        let (direct_range, direct_remainder, records) = direct(source);
        (
            declaration,
            ast_remainder,
            direct_range,
            direct_remainder,
            records,
        )
    }

    let error_role = |role| GrammarRole::Declaration(DeclarationRole::Error(role));
    let variant_role = |role| error_role(ErrorDeclarationRole::Variant(role));
    let close_role = GrammarRole::ClosingDelimiter {
        owner: ConstructRole::EnumBracedVariantBody,
        delimiter: Delimiter::Brace,
    };

    for (source, remainder, at) in [
        ("error", "", 5),
        ("our error", "", 9),
        ("pub error", "", 9),
        ("error {", "{", 6),
        ("error :", ":", 6),
        ("error =", "=", 6),
        ("error ;", ";", 6),
    ] {
        let (ast, ast_remainder, direct_range, direct_remainder, records) = run(source);
        assert!(
            matches!(ast.name, Recovered::Incomplete),
            "Name: {source:?}"
        );
        assert!(
            matches!(ast.body, Recovered::Incomplete),
            "body cascade: {source:?}"
        );
        assert_eq!(ast_remainder, remainder, "AST remainder: {source:?}");
        assert_eq!(direct_remainder, remainder, "direct remainder: {source:?}");
        assert!(
            matches!(direct_range, Recovered::Complete(range) if range.start == ast.range().start)
        );
        assert_eq!(
            records,
            vec![(
                RecoveryKind::Missing,
                error_role(ErrorDeclarationRole::Name),
                at..at
            )],
        );
    }

    for (source, remainder, expected, complete_name) in [
        (
            "error @ E;",
            "",
            vec![(
                RecoveryKind::Error,
                error_role(ErrorDeclarationRole::Name),
                6..8,
            )],
            true,
        ),
        (
            "error @;",
            ";",
            vec![(
                RecoveryKind::Error,
                error_role(ErrorDeclarationRole::Name),
                6..7,
            )],
            false,
        ),
    ] {
        let (ast, ast_remainder, _, direct_remainder, records) = run(source);
        assert_eq!(
            matches!(ast.name, Recovered::Complete(_)),
            complete_name,
            "Name retry: {source:?}"
        );
        assert_eq!(ast_remainder, remainder, "AST remainder: {source:?}");
        assert_eq!(direct_remainder, remainder, "direct remainder: {source:?}");
        assert_eq!(records, expected, "Name recovery: {source:?}");
        assert!(
            records
                .iter()
                .all(|(_, role, _)| *role != error_role(ErrorDeclarationRole::BodyIntroducer))
        );
    }

    for (source, remainder, expected) in [
        (
            "error E 'a @ { A }",
            "",
            vec![(
                RecoveryKind::Error,
                error_role(ErrorDeclarationRole::BodyIntroducer),
                11..13,
            )],
        ),
        (
            "error E @;",
            "",
            vec![(
                RecoveryKind::Error,
                error_role(ErrorDeclarationRole::BodyIntroducer),
                8..9,
            )],
        ),
        (
            "error E @,",
            ",",
            vec![(
                RecoveryKind::Error,
                error_role(ErrorDeclarationRole::BodyIntroducer),
                8..9,
            )],
        ),
    ] {
        let (_, ast_remainder, _, direct_remainder, records) = run(source);
        assert_eq!(ast_remainder, remainder, "AST remainder: {source:?}");
        assert_eq!(direct_remainder, remainder, "direct remainder: {source:?}");
        assert_eq!(records, expected, "BodyIntroducer recovery: {source:?}");
    }

    for (source, expected) in [
        ("error E", vec![]),
        ("error E;", vec![]),
        ("error E {}", vec![]),
        (
            "error E {,A}",
            vec![(
                RecoveryKind::Missing,
                variant_role(VariantDeclarationRole::Item),
                10..10,
            )],
        ),
        (
            "error E {A,,B}",
            vec![(
                RecoveryKind::Missing,
                variant_role(VariantDeclarationRole::Item),
                12..12,
            )],
        ),
        ("error E {A,}", vec![]),
        (
            "error E {A",
            vec![(RecoveryKind::Missing, close_role, 10..10)],
        ),
    ] {
        let (ast, ast_remainder, direct_range, direct_remainder, records) = run(source);
        assert_eq!(ast_remainder, "", "AST remainder: {source:?}");
        assert_eq!(direct_remainder, "", "direct remainder: {source:?}");
        assert_eq!(
            direct_range,
            Recovered::Complete(ast.range()),
            "range: {source:?}"
        );
        assert_eq!(records, expected, "braced recovery: {source:?}");
    }

    let (_, ast_remainder, direct_range, direct_remainder, records) = run("error E {A]");
    assert_eq!(ast_remainder, "]");
    assert_eq!(direct_remainder, "");
    assert_eq!(direct_range, Recovered::Complete(0..11));
    assert_eq!(
        records,
        vec![
            (RecoveryKind::Error, close_role, 10..11),
            (RecoveryKind::Missing, close_role, 11..11),
        ],
    );

    for source in [
        "error E:",
        "error E:;",
        "error E:,",
        "error E:)",
        "error E:\nnext",
    ] {
        let (_, _, _, _, records) = run(source);
        assert_eq!(
            records,
            vec![(
                RecoveryKind::Missing,
                variant_role(VariantDeclarationRole::Item),
                8..8
            )],
            "colon first-item recovery: {source:?}",
        );
    }
    for source in [
        "error E =",
        "error E =;",
        "error E =,",
        "error E =)",
        "error E =\nnext",
    ] {
        let (_, _, _, _, records) = run(source);
        assert_eq!(
            records,
            vec![(
                RecoveryKind::Missing,
                variant_role(VariantDeclarationRole::Item),
                9..9
            )],
            "equals first-item recovery: {source:?}",
        );
    }

    for (source, expected_role) in [
        ("error E = | A |", None),
        ("error E = A || B", Some(VariantDeclarationRole::Item)),
        ("error E { @ A, B }", Some(VariantDeclarationRole::Name)),
        ("error E { @, B }", Some(VariantDeclarationRole::Item)),
        (
            "error E { From from, Next }",
            Some(VariantDeclarationRole::FromType),
        ),
        (
            "error E { Named { : Int }, Next }",
            Some(VariantDeclarationRole::NamedFieldName),
        ),
        (
            "error E { Tuple (, Int) }",
            Some(VariantDeclarationRole::TupleFieldType),
        ),
    ] {
        let (_, ast_remainder, _, direct_remainder, records) = run(source);
        assert_eq!(ast_remainder, "", "AST recovery: {source:?}");
        assert_eq!(direct_remainder, "", "direct recovery: {source:?}");
        match expected_role {
            None => assert!(records.is_empty(), "valid pipe recovery: {source:?}"),
            Some(role) => {
                assert_eq!(records.len(), 1, "one imported ENUM-R record: {source:?}");
                assert_eq!(
                    records[0].1,
                    variant_role(role),
                    "Error outer role: {source:?}"
                );
            }
        }
    }

    for source in [
        "error E { From from @ Int, Next }",
        "error E { Rect @ Int, Next }",
    ] {
        let (_, _, _, direct_remainder, records) = run(source);
        assert_eq!(direct_remainder, "", "payload recovery: {source:?}");
        assert_eq!(records.len(), 1, "one nested Type recovery: {source:?}");
        assert!(
            matches!(records[0].1, GrammarRole::Type(_)),
            "Type role stays inner: {source:?}"
        );
    }
}

#[test]
fn error_gate_9_real_dispatch_reaches_root_and_canonical_statement_owners() {
    fn node_ranges(root: &SyntaxNode, kind: SyntaxKind) -> Vec<Range<usize>> {
        root.descendants()
            .filter(|node| node.kind() == kind)
            .map(|node| syntax_range(node.text_range()))
            .collect()
    }

    fn parse_public_and_direct(
        source: &str,
    ) -> (SyntaxNode, SyntaxNode, DirectRootCandidateOutput) {
        let source_text: Arc<crate::SourceText> = Arc::from(source);
        let header = Arc::new(crate::scan_header(Arc::clone(&source_text)));
        let parsed = crate::parse_file(
            source_text,
            header,
            Arc::new(crate::SyntaxEnvironment::empty()),
        );
        let public = SyntaxNode::new_root(parsed.green().clone());
        let direct =
            parse_direct_root_candidate(source, &crate::operator::OperatorTable::empty(), &[]);
        let direct_root = SyntaxNode::new_root(direct.green().clone());
        assert_eq!(
            public.to_string(),
            source,
            "public losslessness: {source:?}"
        );
        assert_eq!(
            direct_root.to_string(),
            source,
            "direct losslessness: {source:?}"
        );
        assert_eq!(
            node_ranges(&public, SyntaxKind::ErrorDeclaration),
            node_ranges(&direct_root, SyntaxKind::ErrorDeclaration),
            "public/direct Error range parity: {source:?}",
        );
        (public, direct_root, direct)
    }

    fn parse_root_ast(source: &str) -> Range<usize> {
        let mut source_input = SourceInput::new(source);
        let mut local = ParseLocal::new();
        let mut expectations = chasa::LatestSink::new();
        let mut is_cut = false;
        let mut i = In::new(
            &mut source_input,
            &mut expectations,
            IsCut::new(&mut is_cut),
        )
        .set_local(&mut local);
        let Declaration::Error(declaration) = i
            .run(parse_declaration)
            .expect("the promoted root parser recognizes Error")
        else {
            panic!("the exact Error intro must win root declaration dispatch")
        };
        assert_eq!(i.input.remainder(), "", "root AST remainder: {source:?}");
        assert!(
            expectations.take_merged().is_none(),
            "root AST sink: {source:?}"
        );
        assert!(!is_cut, "root AST cut: {source:?}");
        declaration.range()
    }

    // These are ERROR-G's positional, `from`, and contextual-visibility
    // worked examples through the real public entrypoint, not the
    // isolated adapters from Gates 1-8.
    for source in [
        "error fs_err:\n  not_found str\n  denied str",
        "error io_err:\n  fs from fs_err",
        "my error E:\n  failed",
    ] {
        assert_eq!(
            parse_root_ast(source),
            0..source.len(),
            "root AST: {source:?}"
        );
        let (public, _, direct) = parse_public_and_direct(source);
        assert_eq!(
            node_ranges(&public, SyntaxKind::ErrorDeclaration),
            vec![0..source.len()],
            "public Error declaration: {source:?}",
        );
        assert!(
            direct.committed_recoveries().is_empty(),
            "root recovery: {source:?}"
        );
    }

    let nested_ast_source = "error E { A, B }";
    let mut source_input = SourceInput::new(nested_ast_source);
    let mut local = ParseLocal::new();
    let mut expectations = chasa::LatestSink::new();
    let mut is_cut = false;
    let mut i = In::new(
        &mut source_input,
        &mut expectations,
        IsCut::new(&mut is_cut),
    )
    .set_local(&mut local);
    let table = crate::operator::OperatorTable::empty();
    let Some(Statement::Error(declaration)) =
        i.run(from_fn(|i| parse_canonical_statement(&table, i)))
    else {
        panic!("the promoted canonical Statement dispatcher recognizes Error")
    };
    assert_eq!(declaration.range(), 0..nested_ast_source.len());
    assert_eq!(i.input.remainder(), "");
    assert!(expectations.take_merged().is_none());
    assert!(!is_cut);

    // Existing indented and braced statement owners reach the same
    // direct-CST canonical adapter.
    for source in [
        "role Outer:\n  error E { A, B }\n  my value = 1",
        "my block = { error E { A, B }\n  my value = 1 }",
    ] {
        let (public, _, direct) = parse_public_and_direct(source);
        assert!(
            !node_ranges(&public, SyntaxKind::ErrorDeclaration).is_empty(),
            "canonical owner: {source:?}",
        );
        assert!(
            direct.committed_recoveries().is_empty(),
            "owner recovery: {source:?}"
        );
    }

    // ERROR-J's contextual collision proves the shared ordered dispatch:
    // a raw head after `my error` selects Error before Binding, while no
    // head restores Binding authority.
    let (public, direct_root, direct) = parse_public_and_direct("my error E = A");
    assert_eq!(
        node_ranges(&public, SyntaxKind::ErrorDeclaration),
        vec![0..14],
    );
    assert_eq!(
        node_ranges(&public, SyntaxKind::ErrorDeclaration),
        node_ranges(&direct_root, SyntaxKind::ErrorDeclaration),
    );
    assert!(direct.committed_recoveries().is_empty());

    let (public, direct_root, direct) = parse_public_and_direct("my error = 1");
    assert!(node_ranges(&public, SyntaxKind::ErrorDeclaration).is_empty());
    assert_eq!(
        node_ranges(&public, SyntaxKind::BindingStatement),
        vec![0..12]
    );
    assert_eq!(
        node_ranges(&public, SyntaxKind::BindingStatement),
        node_ranges(&direct_root, SyntaxKind::BindingStatement),
    );
    assert!(direct.committed_recoveries().is_empty());

    // Error is full-only: header discovery must stop without producing a
    // header fact, matching the existing rollback arm.
    for source in ["error E { A, B }", "pub error E;"] {
        let source: Arc<crate::SourceText> = Arc::from(source);
        let header = crate::scan_header(source);
        assert_eq!(header.coverage().stop(), crate::HeaderStop::FirstNonHeader);
        assert_eq!(header.coverage().range(), &(0..0));
        assert!(header.imports().is_empty());
        assert!(header.operators().is_empty());
    }
}

#[test]
fn error_gate_10_final_public_scope_and_contextual_word_matrix() {
    fn node_ranges(root: &SyntaxNode, kind: SyntaxKind) -> Vec<Range<usize>> {
        root.descendants()
            .filter(|node| node.kind() == kind)
            .map(|node| syntax_range(node.text_range()))
            .collect()
    }

    fn identifier_tokens(root: &SyntaxNode, text: &str) -> Vec<Range<usize>> {
        root.descendants_with_tokens()
            .filter_map(|element| element.into_token())
            .filter(|token| token.text() == text)
            .map(|token| {
                assert_eq!(
                    token.kind(),
                    SyntaxKind::Identifier,
                    "ordinary word: {text:?}"
                );
                syntax_range(token.text_range())
            })
            .collect()
    }

    fn recovery_node_ranges(root: &SyntaxNode) -> Vec<(SyntaxKind, Range<usize>)> {
        root.descendants()
            .filter(|node| matches!(node.kind(), SyntaxKind::Missing | SyntaxKind::Error))
            .map(|node| (node.kind(), syntax_range(node.text_range())))
            .collect()
    }

    fn parse_public_and_direct(
        source: &str,
    ) -> (SyntaxNode, SyntaxNode, DirectRootCandidateOutput) {
        let source_text: Arc<crate::SourceText> = Arc::from(source);
        let header = Arc::new(crate::scan_header(Arc::clone(&source_text)));
        let parsed = crate::parse_file(
            source_text,
            header,
            Arc::new(crate::SyntaxEnvironment::empty()),
        );
        let public = SyntaxNode::new_root(parsed.green().clone());
        let direct =
            parse_direct_root_candidate(source, &crate::operator::OperatorTable::empty(), &[]);
        let direct_root = SyntaxNode::new_root(direct.green().clone());
        assert_eq!(
            public.to_string(),
            source,
            "public losslessness: {source:?}"
        );
        assert_eq!(
            direct_root.to_string(),
            source,
            "direct losslessness: {source:?}"
        );
        assert_eq!(
            node_ranges(&public, SyntaxKind::ErrorDeclaration),
            node_ranges(&direct_root, SyntaxKind::ErrorDeclaration),
            "public/direct Error range parity: {source:?}",
        );
        assert_eq!(
            recovery_node_ranges(&public),
            recovery_node_ranges(&direct_root),
            "public/direct recovery-node parity: {source:?}",
        );
        assert_eq!(
            direct.committed_recoveries().len(),
            recovery_node_ranges(&direct_root).len(),
            "one record = one recovery node: {source:?}",
        );
        (public, direct_root, direct)
    }

    // ERROR-J permits `my` only when its raw declaration name follows;
    // bare, `our`, and `pub` select the Error declaration immediately.
    for source in ["error E;", "my error E = A", "our error E;", "pub error E;"] {
        let (public, direct_root, direct) = parse_public_and_direct(source);
        assert_eq!(
            node_ranges(&public, SyntaxKind::ErrorDeclaration),
            vec![0..source.len()]
        );
        assert_eq!(
            node_ranges(&direct_root, SyntaxKind::ErrorDeclaration),
            vec![0..source.len()],
        );
        assert!(
            direct.committed_recoveries().is_empty(),
            "visibility recovery: {source:?}"
        );
    }

    // ERROR-G shares Enum's body and payload grammar. Every form reaches
    // the promoted public root, including the normative equals-indent form.
    for source in [
        "error E",
        "error E;",
        "error E { Unit, From from Source, Named { field: Int }, Tuple(Int), Pos Int Str }",
        "error E:\n  Pos Int Str",
        "error E = Pos Int Str",
        "error E =\n  Pos Int Str",
        "error E derives Eq { A }",
        "error E { A } derives Eq",
    ] {
        let (public, direct_root, direct) = parse_public_and_direct(source);
        assert_eq!(
            node_ranges(&public, SyntaxKind::ErrorDeclaration),
            vec![0..source.len()]
        );
        assert_eq!(
            node_ranges(&direct_root, SyntaxKind::ErrorDeclaration),
            vec![0..source.len()],
        );
        assert!(
            direct.committed_recoveries().is_empty(),
            "complete form recovery: {source:?}"
        );
    }

    // Re-run ERROR-R through both promoted entrypoints. These span Error
    // Name and BodyIntroducer recovery plus imported Enum item, payload,
    // field, and closing-delimiter recovery.
    for source in [
        "error",
        "our error",
        "pub error",
        "error {",
        "error :",
        "error =",
        "error ;",
        "error @ E;",
        "error @;",
        "error E 'a @ { A }",
        "error E @;",
        "error E @,",
        "error E {,A}",
        "error E {A,,B}",
        "error E {A",
        "error E {A]",
        "error E:",
        "error E:;",
        "error E:,",
        "error E:)",
        "error E:\nnext",
        "error E =",
        "error E =;",
        "error E =,",
        "error E =)",
        "error E =\nnext",
        "error E = A || B",
        "error E { @ A, B }",
        "error E { @, B }",
        "error E { From from, Next }",
        "error E { Named { : Int }, Next }",
        "error E { Tuple (, Int) }",
        "error E { From from @ Int, Next }",
        "error E { Rect @ Int, Next }",
    ] {
        let (public, direct_root, direct) = parse_public_and_direct(source);
        assert!(
            !node_ranges(&public, SyntaxKind::ErrorDeclaration).is_empty(),
            "public malformed Error owner: {source:?}",
        );
        assert!(
            !recovery_node_ranges(&direct_root).is_empty(),
            "public malformed Error recovery: {source:?}",
        );
        assert_eq!(
            direct.committed_recoveries().len(),
            recovery_node_ranges(&public).len(),
            "public recovery cardinality: {source:?}",
        );
    }

    // `error` and payload-local `from` remain ordinary identifiers away
    // from their accepted declaration and variant-introducer positions.
    for source in [
        "my value = object.error",
        "my value = error",
        "my value: error = output",
        "my value: ({ error: Int }) = output",
        "my result = case value:\n  error -> output",
        "my from = 1",
        "my value = from",
    ] {
        let (public, direct_root, direct) = parse_public_and_direct(source);
        for root in [&public, &direct_root] {
            assert!(
                node_ranges(root, SyntaxKind::ErrorDeclaration).is_empty(),
                "no ErrorDeclaration outside an accepted Statement slot: {source:?}",
            );
            let word = if source.contains("from") {
                "from"
            } else {
                "error"
            };
            assert!(
                !identifier_tokens(root, word).is_empty(),
                "ordinary identifier: {source:?}"
            );
            assert!(
                node_ranges(root, SyntaxKind::FromKw).is_empty(),
                "FromKw only belongs to an Error variant payload: {source:?}",
            );
        }
        assert!(
            direct.committed_recoveries().is_empty(),
            "ordinary-word recovery: {source:?}"
        );
    }

    // The contextual `my` exception still rolls back to Binding through
    // the real public dispatch rather than the isolated Gate 2 recognizer.
    let (public, direct_root, direct) = parse_public_and_direct("my error = 1");
    for root in [&public, &direct_root] {
        assert!(node_ranges(root, SyntaxKind::ErrorDeclaration).is_empty());
        assert_eq!(node_ranges(root, SyntaxKind::BindingStatement), vec![0..12]);
        assert_eq!(identifier_tokens(root, "error"), vec![3..8]);
    }
    assert!(direct.committed_recoveries().is_empty());
}

