{
    for source in [
        "garbage; use std::io",
        "use",
        "prefix (+) 70",
        "my value =",
        "infix (<+>) 50 51 = @@\nmy value = 1",
        "garbage \"unterminated",
    ] {
        assert_direct_root_terminates_with_valid_recovery_shapes(source.to_owned());
    }
}

